<div class="room-list"><?php foreach($rooms as $r):$left=$goodDates?available((int)$r['id'],$in,$out):0; ?><article class="room-card"><img src="<?=e(photo($r['image']))?>" alt="<?=e(t($r['name']))?>"><div><h3><?=e(t($r['name']))?></h3><p><?=e(t($r['description']))?></p><p class="muted"><?=e(t('Up to'))?> <?=e($r['capacity'])?> <?=e(t('guests ·'))?> <?=$left?> <?=e(t('rooms available'))?></p><p><strong><?=money($r['price'])?></strong> <?=e(t('/ night'))?><?php if($goodDates): ?> · <?=$nights?> <?=e(t('nights:'))?> <?=money((float)$r['price']*$nights)?><?php endif ?></p></div><div class="room-book"><?php if($goodDates&&$left>0&&$guests<=(int)$r['capacity']): ?><?php if(is_customer()): ?><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="book"><input type="hidden" name="room_id" value="<?=e($r['id'])?>"><input type="hidden" name="check_in" value="<?=e($in)?>"><input type="hidden" name="check_out" value="<?=e($out)?>"><input type="hidden" name="guests" value="<?=$guests?>"><label><?=e(t('Guest name'))?><input name="guest_name" maxlength="120" value="<?=e($user['name'])?>" required></label><label><?=e(t('Phone'))?><input name="phone" maxlength="40" value="<?=e($user['phone'])?>" required></label><label><?=e(t('Promo code'))?> <span class="muted"><?=e(t('(optional)'))?></span><input name="promo_code" maxlength="30" placeholder="<?=e(t('e.g. FIRSTCHAPTER'))?>"></label><small><?=e(t('One room per booking. Payment proof is due within 24 hours.'))?></small><button class="button"><?=e(t('Reserve this room ↗'))?></button></form><?php elseif($user&&$user['role']==='admin'): ?><span class="badge muted"><?=e(t('Customer account required to book'))?></span><?php else: ?><a class="button" href="<?=e(url('login'))?>"><?=e(t('Sign in to book ↗'))?></a><?php endif ?><?php else: ?><span class="badge muted"><?=e(t('Choose other dates or fewer guests'))?></span><?php endif ?></div></article><?php endforeach ?></div>
